python3 - <<'PY'
from PIL import Image
from pathlib import Path
import json
root = Path('images/fulls')
out = {}
for p in sorted(root.iterdir()):
    if not p.is_file():
        continue
    try:
        with Image.open(p) as img:
            exif = img.getexif()
            data = {}
            mapping = {
                306: 'DateTime',
                36867: 'DateTimeOriginal',
                271: 'Make',
                272: 'Model',
                33434: 'ExposureTime',
                34855: 'ISOSpeedRatings',
                34856: 'ApertureValue',
                34857: 'ShutterSpeedValue',
                34858: 'FocalLength',
                42036: 'LensModel',
            }
            for tag, name in mapping.items():
                if tag in exif:
                    value = exif.get(tag)
                    data[name] = str(value)
            if data:
                out[p.name] = data
    except Exception as e:
        out[p.name] = {'ERROR': f'{type(e).__name__}: {e}'}
Path('.tmp/exif_metadata.json').write_text(json.dumps(out, indent=2, ensure_ascii=False), encoding='utf-8')
print(f'wrote {len(out)} entries to .tmp/exif_metadata.json')
